// Converts raw WordPress/Elementor/Tailwind HTML into clean semantic HTML
// (headings, paragraphs, lists, tables, images, links) with NO classes/styles/scripts,
// so it can be rendered with the Astro site's own design system.
import sanitizeHtml from 'sanitize-html';
import fs from 'node:fs';
import path from 'node:path';
import { imageSize } from 'image-size';

const SITE = /^https?:\/\/(www\.)?atlasaircons\.com/i;

// URLs that exist in the built site (generated by scripts/gen-valid-urls.mjs). If missing, no link is removed.
const VALID: Set<string> | null = (() => {
  try {
    return new Set<string>(JSON.parse(fs.readFileSync('wp-export/valid-urls.json', 'utf8')));
  } catch {
    return null;
  }
})();

const FILE_EXT = /\.(pdf|jpe?g|png|webp|gif|svg|zip|xml|txt|mp4|docx?|xlsx?)$/i;
const dimCache = new Map<string, { width: number; height: number } | null>();
function dims(publicPath: string) {
  if (!dimCache.has(publicPath)) {
    try {
      const d = imageSize(fs.readFileSync(path.join('public', decodeURIComponent(publicPath))));
      dimCache.set(publicPath, d.width && d.height ? { width: d.width, height: d.height } : null);
    } catch {
      dimCache.set(publicPath, null);
    }
  }
  return dimCache.get(publicPath)!;
}

/** Internal page links: strip .html, force trailing slash, /home -> / . Leaves files/external/mailto/tel alone. */
function normHref(href: string): string {
  if (!href.startsWith('/') || href.startsWith('//')) return href;
  // If URL has trailing slash after a file extension like .avif/, clean it
  href = href.replace(/(\.(?:avif|webp|png|jpe?g|pdf|svg|zip))\/(?=[?#]|$)/i, '$1');
  if (FILE_EXT.test(href.split(/[?#]/)[0])) return href;
  const m = href.match(/^([^?#]*)(.*)$/)!;
  let p = m[1].replace(/\.html?$/i, '');
  if (p === '/home' || p === '/home/') p = '/';
  if (!p.endsWith('/')) p += '/';
  return p + m[2];
}

export interface CleanResult {
  title: string | null; // first <h1> text, if any
  html: string;
}

const textOf = (s: string) => s.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();

export function cleanWpHtml(raw: string): CleanResult {
  let html = raw
    // WP / builder comments and leftover <p><style> wrappers
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<svg[\s\S]*?<\/svg>/gi, '');

  html = sanitizeHtml(html, {
    allowedTags: [
      'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'ul', 'ol', 'li', 'a', 'strong', 'b', 'em', 'i',
      'br', 'blockquote', 'img', 'figure', 'figcaption', 'table', 'thead', 'tbody', 'tfoot',
      'tr', 'th', 'td', 'iframe', 'hr', 'details', 'summary', 'sup', 'sub',
    ],
    allowedAttributes: {
      a: ['href', 'title', 'target', 'rel'],
      img: ['src', 'alt', 'width', 'height', 'loading', 'decoding'],
      iframe: ['src', 'title', 'width', 'height', 'allowfullscreen'],
      td: ['colspan', 'rowspan'],
      th: ['colspan', 'rowspan'],
    },
    allowedIframeHostnames: ['www.youtube.com', 'www.google.com', 'maps.google.com', 'player.vimeo.com'],
    // drop the contents of these entirely (UI chrome, not content)
    nonTextTags: ['style', 'script', 'textarea', 'option', 'button', 'form', 'noscript', 'select', 'svg', 'nav'],
    // unwrap everything else (div, section, span, i, etc. keep their text)
    disallowedTagsMode: 'discard',
    transformTags: {
      // decorative icon tags (<i class="fa ..."></i>) become empty and get removed below
      b: 'strong',
      img: (_t, attribs) => {
        let src = (attribs.src || '').replace(/&#0*38;|&amp;/g, '&').replace(SITE, '').split('?')[0];
        // use the local copy (public/wp-content/...) when it was downloaded; otherwise keep the live URL
        if (src.startsWith('/wp-content/')) {
          src = fs.existsSync(path.join('public', decodeURIComponent(src))) ? src : 'https://www.atlasaircons.com' + src;
        }
        const out: Record<string, string> = { src, alt: attribs.alt || '', loading: 'lazy', decoding: 'async' };
        if (attribs.width) out.width = attribs.width;
        if (attribs.height) out.height = attribs.height;
        if ((!out.width || !out.height) && src.startsWith('/wp-content/')) {
          const d = dims(src);
          if (d) {
            out.width = String(d.width);
            out.height = String(d.height);
          }
        }
        return { tagName: 'img', attribs: out };
      },
      i: (_t, attribs) => ({ tagName: 'i', attribs: /\bfa[srbl]?\b|fa-/.test(attribs.class || '') ? { 'data-icon': '1' } : {} }),
      a: (tag, attribs) => {
        const href = attribs.href || '';
        const out: Record<string, string> = {};
        if (href) out.href = normHref(SITE.test(href) ? href.replace(SITE, '') || '/' : href);
        if (attribs.target === '_blank') {
          out.target = '_blank';
          out.rel = 'noopener noreferrer';
        }
        return { tagName: 'a', attribs: out };
      },
    },
    exclusiveFilter: (frame) => {
      if (frame.tag === 'i' && frame.attribs['data-icon']) return true;
      if (frame.tag === 'img') return !frame.attribs.src;
      if (['iframe', 'hr', 'br', 'td', 'th', 'tr'].includes(frame.tag)) return false;
      // remove empty elements
      return !frame.text.trim() && !frame.mediaChildren.length;
    },
  });

  // Remove dead internal links (target page does not exist) but keep the visible text. URLs are never changed.
  html = html.replace(/href="(\/wp-content\/uploads\/[^"]*?\.(?:avif|webp|png|jpe?g|pdf|svg|zip))\/"/gi, 'href="$1"');

  if (VALID) {
    html = html.replace(/<a href="(\/[^"]*)"([^>]*)>([\s\S]*?)<\/a>/g, (full, href, rest, inner) => {
      if (href.startsWith('//')) return full;
      const p = decodeURIComponent(href.split(/[?#]/)[0]);
      if (FILE_EXT.test(p) || p.startsWith('/wp-content/')) return full;
      return VALID.has(p) ? full : inner;
    });
  }

  // Pull out the first H1 as the page title; demote any further H1 to H2 (one H1 per page)
  let title: string | null = null;
  html = html.replace(/<h1>([\s\S]*?)<\/h1>/g, (_m, inner) => {
    if (title === null) {
      title = textOf(inner);
      return '';
    }
    return `<h2>${inner}</h2>`;
  });

  // collapse leftover whitespace
  html = html.replace(/(\s*\n\s*){3,}/g, '\n\n').trim();
  return { title, html };
}
